examples.code:
SELECT x, y, hilbert_encode([x, y]::UINTEGER[2]) AS hilbert
FROM (VALUES (1, 1), (1, 2), (2, 1), (6, 7), (7, 6)) AS t(x, y)
ORDER BY hilbert;

SELECT x, y, hilbert_encode(x, y) AS key
FROM (VALUES (-3, 2), (0, 0), (4, -1)) AS t(x, y)
ORDER BY key;

SELECT x, y, morton_encode([x, y]::UINTEGER[2]) AS morton
FROM (VALUES (1, 1), (1, 2), (2, 1), (6, 7), (7, 6)) AS t(x, y)
ORDER BY morton;

SELECT x, y, morton_encode(x, y) AS key
FROM (VALUES (-3, 2), (0, 0), (4, -1)) AS t(x, y)
ORDER BY key;
